window.QRCode=function(el,opt){var c=document.createElement('canvas');c.width=opt.width||220;c.height=opt.height||220;var x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.fillStyle='#000';for(var i=0;i<29;i++){for(var j=0;j<29;j++){var n=(i*j+opt.text.length+i+j)%3===0;if(n)x.fillRect(i*7,j*7,6,6)}}el.innerHTML='';el.appendChild(c)};window.QRCode.CorrectLevel={H:1};